out failing on unknown CRDs.","tree":{"sha":"de63dd554719d0a63e3db3f6c65f4908b932332b","url":"https://api.github.com/repos/dankli/OspreyLoyalty/git/trees/de63dd554719d0a63e3db3f6c65f4908b932332b"},"url":"https://api.github.com/repos/dankli/OspreyLoyalty/git/commits/0b87bcdda38cda56c4b4d9ef44fa05f0daa8be0a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/138536?v=4","events_url":"https://api.github.com/users/dankli/events{/privacy}","followers_url":"https://api.github.com/users/dankli/followers","following_url":"https://api.github.com/users/dankli/following{/other_user}","gists_url":"https://api.github.com/users/dankli/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/dankli","id":138536,"login":"dankli","node_id":"MDQ6VXNlcjEzODUzNg==","organizations_url":"https://api.github.com/users/dankli/orgs","received_events_url":"https://api.github.com/users/dankli/received_events","repos_url":"https://api.github.com/users/dankli/repos","site_admin":false,"starred_url":"https://api.github.com/users/dankli/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dankli/subscriptions","type":"User","url":"https://api.github.com/users/dankli","user_view_type":"public"},"html_url":"https://github.com/dankli/OspreyLoyalty/commit/0b87bcdda38cda56c4b4d9ef44fa05f0daa8be0a","node_id":"C_kwDOTPCIxtoAKDBiODdiY2RkYTM4Y2RhNTZjNGI0ZDllZjQ0ZmEwNWYwZGFhOGJlMGE","parents":[{"html_url":"https://github.com/dankli/OspreyLoyalty/commit/443b88c7d6692dae612bdcae5360d4cda7f4fdcd","sha":"443b88c7d6692dae612bdcae5360d4cda7f4fdcd","url":"https://api.github.com/repos/dankli/OspreyLoyalty/commits/443b88c7d6692dae612bdcae5360d4cda7f4fdcd"}],"sha":"0b87bcdda38cda56c4b4d9ef44fa05f0daa8be0a","url":"https://api.github.com/repos/dankli/OspreyLoyalty/commits/0b87bcdda38cda56c4b4d9ef44fa05f0daa8be0a"},{"author":{"avatar_url":"https://avatars.githubuserconten